'use client';

import { useState } from 'react';
import { useWorkflow } from '@/hooks/useWorkflow';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';

interface CompleteRegistrationDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const EMPTY_FORM = {
  guestName: '',
  email: '',
  phone: '',
  category: 'Delegate' as 'VIP' | 'Speaker' | 'Delegate' | 'Staff' | 'Press',
  eventTitle: '',
  paymentAmount: '',
};

export function CompleteRegistrationDialog({ open, onOpenChange }: CompleteRegistrationDialogProps) {
  const { completeRegistration, loading } = useWorkflow();
  const { toast } = useToast();
  const [form, setForm] = useState(EMPTY_FORM);

  const set = (field: keyof typeof EMPTY_FORM) => (e: React.ChangeEvent<HTMLInputElement>) =>
    setForm((prev) => ({ ...prev, [field]: e.target.value }));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const result = await completeRegistration({
      ...form,
      eventId: '',
      eventTitle: form.eventTitle,
      paymentAmount: form.paymentAmount ? Number(form.paymentAmount) : undefined,
    });
    if (result.success) {
      toast({ title: 'Registered!', description: `${form.guestName} registered for ${form.eventTitle}.` });
      onOpenChange(false);
      setForm(EMPTY_FORM);
    } else {
      toast({ title: 'Failed', description: result.error || 'Could not complete registration.', variant: 'destructive' });
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>New Registration</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit}>
          <div className="space-y-3 py-3">
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1 col-span-2">
                <Label htmlFor="guestName">Full Name *</Label>
                <Input id="guestName" value={form.guestName} onChange={set('guestName')} placeholder="Jane Smith" required />
              </div>
              <div className="space-y-1">
                <Label htmlFor="email">Email *</Label>
                <Input id="email" type="email" value={form.email} onChange={set('email')} placeholder="jane@example.com" required />
              </div>
              <div className="space-y-1">
                <Label htmlFor="phone">Phone</Label>
                <Input id="phone" value={form.phone} onChange={set('phone')} placeholder="(415) 555-0000" />
              </div>
              <div className="space-y-1">
                <Label htmlFor="eventTitle">Event *</Label>
                <Input id="eventTitle" value={form.eventTitle} onChange={set('eventTitle')} placeholder="Tech Summit 2024" required />
              </div>
              <div className="space-y-1">
                <Label>Category</Label>
                <Select value={form.category} onValueChange={(v) => setForm((p) => ({ ...p, category: v as typeof form.category }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {['VIP', 'Speaker', 'Delegate', 'Staff', 'Press'].map((c) => (
                      <SelectItem key={c} value={c}>{c}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1 col-span-2">
                <Label htmlFor="paymentAmount">Fee ($) <span className="text-muted-foreground text-xs">(optional)</span></Label>
                <Input id="paymentAmount" type="number" min="0" step="0.01" value={form.paymentAmount} onChange={set('paymentAmount')} placeholder="0.00" />
              </div>
            </div>
          </div>
          <DialogFooter className="pt-2">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={loading}>Cancel</Button>
            <Button type="submit" disabled={loading || !form.guestName.trim() || !form.email.trim() || !form.eventTitle.trim()}>
              {loading ? 'Saving…' : 'Register'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}